import { chromium } from 'file:///D:/app/itatest/tests/browser/node_modules/playwright/index.mjs'
import assert from 'node:assert/strict'
import { writeFileSync } from 'node:fs'
import { api, root, artifact, browserOptions, requireLocalPreview } from 'file:///D:/app/itatest/tests/browser/environment.mjs'

await requireLocalPreview()
async function request(path, token, method = 'GET', body) {
  const response = await fetch(api + path, { method, headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) }, body: body ? JSON.stringify(body) : undefined })
  assert.ok(response.ok, `${path}: ${response.status} ${response.ok ? '' : await response.text()}`)
  return response.status === 204 ? null : response.json()
}
const admin = await request('/auth/login', null, 'POST', { email: 'admin@cent.local', password: 'cent-local-preview-only' })
const learner = await request('/auth/register', null, 'POST', { email: `notes-${Date.now()}@test.local`, name: 'Notes regression', password: 'notes-local-check' })
const curriculum = await request('/curriculum')
const course = curriculum.courses.find(c => c.code === 'math')
assert.ok(course, 'Import the curriculum before running this check.')
const productId = crypto.randomUUID()
await request(`/admin/products/${productId}`, admin.token, 'PUT', { title: 'Local notes verification', kind: 'TRAINING', trainingId: course.trainingId, priceRial: 10000, durationDays: null, active: true })
const order = await request('/checkout', learner.token, 'POST', { productId, requestId: crypto.randomUUID() })
await request(`/me/orders/${order.id}/verify`, learner.token, 'POST', {})
const doc = curriculum.documents.find(d => d.trainingId === course.trainingId)
const browser = await chromium.launch(browserOptions)
try {
  const page = await browser.newPage({ viewport: { width: 1365, height: 950 } })
  const errors = [], savedIds = []
  page.on('pageerror', e => errors.push(e.message))
  await page.goto(root + '/')
  await page.evaluate(token => sessionStorage.setItem('cent:session:v1', token), learner.token)
  await page.goto(`${root}/student/study/${doc.id}`)
  await page.locator('.cent-source-text > div').filter({ hasText: /.+/ }).waitFor()
  const editor = page.getByLabel('متن یادداشت')
  const saveButton = page.getByRole('button', { name: 'ثبت یادداشت', exact: true })
  const newButton = page.getByRole('button', { name: 'یادداشت جدید', exact: true })
  const noteText = '.cent-page-notes .cent-note-text p'
  async function save(text) {
    await editor.fill(text)
    const response = page.waitForResponse(r => r.request().method() === 'PUT' && new URL(r.url()).pathname.includes('/notes/'))
    await saveButton.click()
    const saved = await response
    assert.equal(saved.status(), 200, `Saving '${text}': ${await saved.text()}`)
    const note = await saved.json()
    await page.locator('.cent-save-status').filter({ hasText: 'در حساب شما ذخیره شد' }).waitFor()
    return note.id
  }
  for (let i = 1; i <= 3; i++) {
    if (i > 1) await newButton.click()
    savedIds.push(await save(`Consecutive note ${i}`))
    assert.equal(await page.locator(noteText).count(), i)
  }
  assert.equal(new Set(savedIds).size, 3)
  // Updating a selected note must edit that note, without replacing another one.
  await page.locator('.cent-note-text').filter({ hasText: 'Consecutive note 1' }).click()
  assert.equal(await save('Consecutive note 1 edited'), savedIds[0])
  await newButton.click()
  savedIds.push(await save('New note after editing'))
  assert.equal(new Set(savedIds).size, 4)
  // A failed request keeps its creation ID for retry instead of creating duplicates.
  await newButton.click()
  let retryId
  await page.route('**/notes/*', async route => {
    if (route.request().method() !== 'PUT') return route.continue()
    retryId = route.request().url().split('/').at(-1)
    return route.fulfill({ status: 503, contentType: 'application/json', body: JSON.stringify({ message: 'Temporary notes check failure' }) })
  }, { times: 1 })
  await editor.fill('Note after retry')
  await saveButton.click()
  await page.getByText('Temporary notes check failure', { exact: true }).waitFor()
  savedIds.push(await save('Note after retry'))
  assert.equal(savedIds.at(-1), retryId)
  assert.equal(new Set(savedIds).size, 5)
  await page.reload()
  await page.locator(noteText).filter({ hasText: 'Note after retry' }).waitFor()
  const stored = await request(`/documents/${doc.id}`, learner.token)
  assert.equal(stored.notes.length, 5)
  assert.equal(new Set(stored.notes.map(n => n.id)).size, 5)
  assert.deepEqual(stored.notes.map(n => n.body).sort(), ['Consecutive note 1 edited', 'Consecutive note 2', 'Consecutive note 3', 'New note after editing', 'Note after retry'].sort())
  assert.deepEqual(errors, [])
  await page.screenshot({ path: artifact('phase1-safe-notes.png'), fullPage: true })
  writeFileSync(artifact('phase1-safe-notes-result.json'), JSON.stringify({ success: true, persistedNotes: 5, checked: ['three consecutive creations', 'edit then create', 'failed request retry', 'reload persistence'], browserErrors: errors }, null, 2))
  console.log('Notes checks passed: consecutive notes, editing, retry, five distinct notes persisted after reload.')
} finally { await browser.close() }

import { readFileSync } from 'node:fs'
import { chromium } from 'file:///D:/app/itatest/tests/browser/node_modules/playwright/index.mjs'
import { writeFileSync } from 'node:fs'
import { api, root, artifact, browserOptions, requireLocalPreview } from 'file:///D:/app/itatest/tests/browser/environment.mjs'
await requireLocalPreview()
const login=async email=>fetch(api+'/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password:'cent-local-preview-only'})}).then(r=>r.json())
const admin=await login('admin@cent.local');const users=await fetch(api+'/admin/users',{headers:{Authorization:'Bearer '+admin.token}}).then(r=>r.json())
const fixture=JSON.parse(readFileSync('D:/app/itatest/tests/browser/artifacts/result.json','utf8'))
const orders=await fetch(api+'/admin/orders',{headers:{Authorization:'Bearer '+admin.token}}).then(r=>r.json())
const ownOrder=orders.find(o=>o.trainingId===fixture.trainingId)
if(!ownOrder)throw Error('This smoke fixture has no order')
const ownStudent=users.find(u=>u.id===ownOrder.userId)
if(!ownStudent?.email.startsWith('study-'))throw Error('Not a smoke learner')
const student=await login(ownStudent.email)
const notes=await fetch(api+'/me/notes',{headers:{Authorization:'Bearer '+student.token}}).then(r=>r.json());const note=notes.find(n=>n.page===2)
if(!note)throw new Error('No second-page note in the browser fixture')
const browser=await chromium.launch(browserOptions)
try {
 const page=await browser.newPage({viewport:{width:1440,height:1000}})
 await page.goto(root+'/login');await page.evaluate(token=>sessionStorage.setItem('cent:session:v1',token),student.token)
 let failures=0;await page.route(/\/api\/cent\/v1\/me$/,async route=>{if(failures++<2)await route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({message:'Temporary test interruption'})});else await route.continue()})
 await page.goto(root+'/student/study/'+note.documentId+'?page=2');await page.getByText(note.body,{exact:true}).waitFor({timeout:45000});await page.waitForFunction(()=>!document.querySelector('.cent-page-content.concealed'));await page.screenshot({path:artifact('phase1-targeted-recovery.png'),fullPage:true})
 if(failures<3)throw new Error('Recovery did not retry the session check')
 writeFileSync(artifact('phase1-targeted-recovery-result.json'),JSON.stringify({success:true,transientFailures:2,restoredWithoutLogin:true,page:2},null,2));console.log('Recovery passed: two 503 responses, same session restored, correct page and private note visible.')
} finally {await browser.close()}
